scenarios.example_code:
import { submitMeasurement } from '@projexlight/hdk-measure';
const { measurement_id } = await submitMeasurement({
  tenant_id, persona_id, device_uuid,
  kind: 'area', value: 18.4, units: 'm2',
  sensor_metadata: { ar_session_id, lidar_used: true },
});

import { disputeMeasurement } from '@projexlight/hdk-measure';
await disputeMeasurement({
  measurement_id, reason: 'value-too-small-for-context',
  reviewer_persona_id,
});
